(() => {
  const clean = (s) => ((s || '') + '').trim();
  const vis = (e) => { const r = e.getBoundingClientRect(); return r.width > 2 && r.height > 2; };
  const box = [...document.querySelectorAll('.ui-suggest')].filter(vis)[0];
  const 公司 = [...document.querySelectorAll('input')].find((x) => (x.placeholder || '').includes('北京华品博睿'));
  return {
    公司值: 公司 ? clean(公司.value) : '没框',
    建议框文字: box ? clean(box.innerText).slice(0, 600) : '没弹建议框',
    条目: box ? [...box.querySelectorAll('li,div')].map((x) => x.tagName + '.' + (x.className || '').toString().slice(0, 26) + ':' + clean(x.innerText).slice(0, 40)).filter((t) => t.length > 8).slice(0, 14) : []
  };
})()
